def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to separate build metadata
        version_part, _, build = v.partition('+')

        # Split by '-' to separate pre-release
        core_part, _, prerelease = version_part.partition('-')

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
        else:
            prerelease_ids = None

        return (major, minor, patch, prerelease_ids)

    def compare_prerelease(pre1, pre2):
        # If one has pre-release and other doesn't, the one without sorts later
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # version without pre-release sorts after
        if pre2 is None:
            return -1  # version with pre-release sorts before

        # Compare pre-release identifiers
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric, compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 < num2:
                    return -1
                elif num1 > num2:
                    return 1
            elif is_digit1:
                # Numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric, compare lexically
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # All shared identifiers equal, fewer sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    def sort_key(v):
        parsed = parse_version(v)
        major, minor, patch, prerelease = parsed

        # Create a sort key tuple
        # For pre-release: use a special value to handle sorting
        if prerelease is None:
            # No pre-release: this should sort after pre-release
            prerelease_key = (1,)  # Higher value sorts later
        else:
            # Has pre-release: this should sort before non-prerelease
            prerelease_key = (0, tuple(
                (0, int(id)) if id.isdigit() else (1, id)
                for id in prerelease
            ))

        return (major, minor, patch, prerelease_key)

    # Sort with stable sort to preserve input order for equal versions
    return sorted(versions, key=sort_key)

